import sys
from collections import defaultdict

sys.setrecursionlimit(10**6)

def dfs(node, parent, graph, visited, depth):
    visited[node] = True
    for neighbor in graph[node]:
        if not visited[neighbor]:
            depth[neighbor] = depth[node] + 1
            if dfs(neighbor, node, graph, visited, depth):
                return True
        elif neighbor != parent and depth[neighbor] % 2 == depth[node] % 2:
            return True
    return False

def find_odd_cycle(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    depth = [0] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i, -1, graph, visited, depth):
                return True
    return False

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]

    if find_odd_cycle(n, edges):
        print(0, 1)
        return

    if m == 0:
        print(3, 1)
        return

    if m == n * (n - 1) // 2:
        print(1, 1)
        return

    print(1, m)

if __name__ == "__main__":
    main()
